content.text:
export type Cell = [number, number];

export function nextGeneration(cells: Cell[]): Cell[] {
  return [];
}

import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  // Simplest case
  it("should return empty array for empty input -- []", () => {
    expect(nextGeneration([])).toEqual([]);
  });

  // Rule 1: Underpopulation
  it.todo("should kill a single live cell with 0 neighbors -- [(0,0)] -> []");
  it.todo("should kill two adjacent cells each with 1 neighbor -- [(0,1),(1,1)] -> []");

  // Rule 2: Survival (covered via blinker/block patterns)

  // Rule 3: Overpopulation
  it.todo("should kill the center cell of a 3x3 full block when it has 4+ neighbors -- center (1,1) dies");

  // Rule 4: Reproduction
  it.todo("should bring a dead cell with exactly 3 neighbors to life -- L-shape produces (1,1)");

  // Pattern: Block (still life) - tests Rule 2 (survival with 3 neighbors)
  it.todo("should leave a 2x2 block unchanged (still life) -- [(0,0),(1,0),(0,1),(1,1)] unchanged");

  // Pattern: Blinker (oscillator) - tests Rules 1, 2, 4 with negative coords
  it.todo("should transform vertical blinker into horizontal blinker -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");
});

