import { describe, it, expect } from "vitest";
import { nextGeneration, type Cell } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  // Simplest case
  it("should return empty array for empty input -- []", () => {
    expect(nextGeneration([])).toEqual([]);
  });

  // Rule 1: Underpopulation
  it("should kill a single live cell with 0 neighbors -- [(0,0)] -> []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });
  it("should kill two adjacent cells each with 1 neighbor -- [(0,1),(1,1)] -> []", () => {
    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
  });

  // Rule 2: Survival (covered via blinker/block patterns)

  // Rule 3: Overpopulation
  it("should kill the center cell of a 3x3 full block when it has 4+ neighbors -- center (1,1) dies", () => {
    const fullBlock3x3: Cell[] = [
      [0, 0], [1, 0], [2, 0],
      [0, 1], [1, 1], [2, 1],
      [0, 2], [1, 2], [2, 2],
    ];
    const result = nextGeneration(fullBlock3x3);
    const containsCenter = result.some(([x, y]) => x === 1 && y === 1);
    expect(containsCenter).toBe(false);
  });

  // Rule 4: Reproduction
  it("should bring a dead cell with exactly 3 neighbors to life -- L-shape produces (1,1)", () => {
    const lShape: Cell[] = [[0, 0], [1, 0], [0, 1]];
    const result = nextGeneration(lShape);
    const containsNewCell = result.some(([x, y]) => x === 1 && y === 1);
    expect(containsNewCell).toBe(true);
  });

  // Pattern: Block (still life) - tests Rule 2 (survival with 3 neighbors)
  it.todo("should leave a 2x2 block unchanged (still life) -- [(0,0),(1,0),(0,1),(1,1)] unchanged");

  // Pattern: Blinker (oscillator) - tests Rules 1, 2, 4 with negative coords
  it.todo("should transform vertical blinker into horizontal blinker -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");
});

All 5 tests pass. Let me analyze.

## Step 1: Naming Evaluation

- `nextGeneration(liveCells)` — clearly reveals intent (Game of Life term). **Keep.**
- `cellKey(x, y)` — clear, describes purpose. **Keep.**
- `liveSet`, `neighborCounts`, `survives`, `born` — all reveal intent well. **Keep.**

No naming issues.

## Step 2: Calculate Initial APP Mass

```
export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveSet = new Set(liveCells.map(([x, y]) => cellKey(x, y)));
  const neighborCounts = new Map<string, number>();
  for (const [x, y] of liveCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const key = cellKey(x + dx, y + dy);
        neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
      }
    }
  }
  const result: Cell[] = [];
  for (const [key, count] of neighborCounts) {
    const isAlive = liveSet.has(key);
    const survives = isAlive && (count === 2 || count === 3);
    const born = !isAlive && count === 3;
    if (survives || born) {
      const [xs, ys] = key.split(",");
      result.push([Number(xs), Number(ys)]);
    }
  }
  return result;
}
```

Rough count (cellKey helper):
- Bindings: x, y → 2; Invocations: template literal ≈ 1. Mass ≈ 3.

nextGeneration:
- Constants: -1, 1, -1, 1, 0, 0, 0, 1, 2, 3, 3, "," → 12
- Bindings: liveCells, liveSet, x, y, neighborCounts, x, y, dx, dy, key, key, count, isAlive, survives, born, xs, ys, result → ~18
- Invocations: new Set, map, cellKey, new Map, cellKey (inner), set, get, ??, +, +, +, has, split, push, Number×2 → ~16 → ×2 = 32
- Conditionals: `if (dx===0 && dy===0)`, `count===2 || count===3`, `count===3`, `survives || born` → ~4 conditionals = 16
- Loops: outer for-of, dx loop, dy loop, result for-of → 4 = 20
- Assignments: dx++, dy++ → 2 = 12

**Total ≈ 12 + 18 + 32 + 16 + 20 + 12 = 110** (plus helper 3 = ~113)

## Step 3: Apply Simple Design Rules

**Rule 3 (DRY)**: The pattern `key.split(",")` then `Number(xs), Number(ys)` is the inverse of `cellKey`. This is conceptual duplication — we have key encoding in one place but decoding inline. Let's extract `parseCellKey`.

**Rule 2 (Intent)**: Extracting the neighbor-offset iteration into a `neighborOffsets` constant array would reveal intent more directly than nested loops with skip-self conditional. This also reduces conditionals and the `dx++/dy++` assignments.

Let me apply both refactorings (one at a time, tests after each).

### Refactoring 1: Extract neighbor offsets constant

